fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();

    // Choose a split point so that:
    // - left.len() + right.len() == n
    // - left ++ right == a
    // - if n > 1, both parts are strictly shorter than n
    let mid = match n {
        0 => 0,
        1 => 0,            // one part will be length 0, the other length 1 (allowed)
        _ => n / 2,        // ensures 1..n-1
    };

    let left = a[..mid].to_vec();
    let right = a[mid..].to_vec();
    (left, right)
}